package com.zhineng.platform.evaluation.performance.excel;
import java.io.*;import java.util.*;import org.apache.poi.ss.usermodel.*;import org.apache.poi.xssf.usermodel.XSSFWorkbook;import org.springframework.stereotype.Component;
@Component public class PerformanceExcelService{
 public byte[] template(){try(XSSFWorkbook wb=new XSSFWorkbook();ByteArrayOutputStream out=new ByteArrayOutputStream()){Sheet s=wb.createSheet("组织部绩效数据");String[] h={"机构编码","机构名称","年度","绩效等次","重点工作得分","班子评价","备注"};Row r=s.createRow(0);for(int i=0;i<h.length;i++){r.createCell(i).setCellValue(h[i]);s.setColumnWidth(i,4200);}Row sample=s.createRow(1);Object[] v={"KLMY-BB","示例机构",2026,"A",92.5,"优秀","请删除示例行"};for(int i=0;i<v.length;i++){if(v[i]instanceof Number n)sample.createCell(i).setCellValue(n.doubleValue());else sample.createCell(i).setCellValue(v[i].toString());}wb.write(out);return out.toByteArray();}catch(IOException e){throw new IllegalStateException(e);}}
 public WorkbookData read(byte[] bytes){try(XSSFWorkbook wb=new XSSFWorkbook(new ByteArrayInputStream(bytes))){Sheet s=wb.getSheetAt(0);DataFormatter f=new DataFormatter();Row header=s.getRow(s.getFirstRowNum());List<String> headers=new ArrayList<>();for(Cell c:header)headers.add(f.formatCellValue(c).trim());List<RowData> rows=new ArrayList<>();for(int i=header.getRowNum()+1;i<=s.getLastRowNum();i++){Row row=s.getRow(i);if(row==null)continue;Map<String,String> values=new LinkedHashMap<>();boolean any=false;for(int j=0;j<headers.size();j++){String value=f.formatCellValue(row.getCell(j,Row.MissingCellPolicy.CREATE_NULL_AS_BLANK)).trim();values.put(headers.get(j),value);any|=!value.isBlank();}if(any)rows.add(new RowData(i+1,values));}return new WorkbookData(headers,rows);}catch(Exception e){throw new IllegalArgumentException("无法读取XLSX："+e.getMessage());}}
 public record RowData(int rowNumber,Map<String,String> values){}
 public record WorkbookData(List<String> headers,List<RowData> rows){}
}
